# Task: make the gateway spec-compliant

The `src/gateway.js` module violates the project's documented API contract.
The authoritative specification lives somewhere in `docs/` — a series of
architecture decision records (ADRs). Somewhere in those ADRs the exact
required header names and the exhaustion behavior are specified (mind the
ADR series' internal supersession notes — later decisions may override
earlier ones).

Rules:
- You may only edit `src/gateway.js`. Do not modify tests or docs.
- All tests must pass.

Verify: `bash verify.sh`.
---
// Simple quota gateway. BUG: missing required headers per the project docs.
function respond(status, quotaRemaining) {
    const headers = {};
    if (quotaRemaining <= 0) {
        headers['RateLimit'] = String(quotaRemaining); // wrong name, missing Retry-After
    } else {
        headers['rate-limit'] = String(quotaRemaining); // wrong case
    }
    return { status, headers };
}
module.exports = { respond };
---
gateway.test.js
const { respond } = require('../src/gateway.js');
const assert = require('assert');
assert.strictEqual(respond(200, 42).headers['X-Rate-Limit'], '42', 'normal path: X-Rate-Limit as decimal string');
const limited = respond(429, 0);
assert.strictEqual(limited.status, 429, 'exhausted path: 429');
assert.strictEqual(limited.headers['X-Rate-Limit'], '0', 'exhausted path: X-Rate-Limit present');
assert.strictEqual(limited.headers['Retry-After'], '30', 'exhausted path: Retry-After 30');
assert.strictEqual(limited.headers['RateLimit'], undefined, 'no malformed header names');
console.log('gateway tests OK');

