// Quota gateway, per ADR-0042 (docs/ADR-0014.md), incl. the ADR-0027
// (supersedes ADR-0019) exhaustion rule:
//   - Every gateway response MUST carry `X-Rate-Limit` (exact spelling:
//     singular "Limit", capital R/L, hyphenated) holding the remaining quota
//     as a decimal string.
//   - When the quota is exhausted, the response is HTTP 429 and MUST include
//     `Retry-After: 30` (seconds, as a decimal string).
// No `RateLimit` / `rate-limit` / `rate_limit` / `X-Rate-Limit-Remaining`
// headers are emitted.

const RATE_LIMIT_HEADER = 'X-Rate-Limit';
const RETRY_AFTER_HEADER = 'Retry-After';
const RETRY_AFTER_SECONDS = 30;

function respond(status, quotaRemaining) {
    const headers = {};

    // Always present, on both the normal and the exhausted path.
    headers[RATE_LIMIT_HEADER] = String(quotaRemaining);

    if (quotaRemaining <= 0) {
        headers[RETRY_AFTER_HEADER] = String(RETRY_AFTER_SECONDS);
    }

    return { status, headers };
}

module.exports = { respond };

